  void OnShown(object sender,EventArgs e){if(args.Contains("--no-watch"))Watch.Checked=false;if(args.Length>=2&&args[0]=="--self-test")RunSelfTest(args[1]);else if(args.Length>=2&&args[0]=="--open")StartScan(args[1]);}
  void ChooseFolder(){using(var dialog=new FolderBrowserDialog{Description="분석할 폴더 또는 드라이브를 선택하세요.",SelectedPath=PathBox.Text,ShowNewFolderButton=false})if(dialog.ShowDialog(this)==DialogResult.OK){PathBox.Text=dialog.SelectedPath;StartScan(dialog.SelectedPath);}}
  internal async void StartScan(string input){if(scan!=null)return;string path;try{path=Path.GetFullPath(input.Trim());if(!Directory.Exists(path))throw new DirectoryNotFoundException("폴더가 없거나 접근할 수 없습니다.");}catch(Exception ex){Status.Text=ex.Message;return;}
   bool retain=snapshot!=null&&!offline&&String.Equals(snapshot.root,path,StringComparison.OrdinalIgnoreCase);Snapshot previous=retain?snapshot:null;
   if(!retain){snapshot=null;projection=null;focus=0;history.Clear();Map.Clear();Listing.VirtualListSize=0;Total.Text="";}PathBox.Text=path;PathLabel.Text=path;offline=false;generation++;long token=generation;UpdateCapacity(path,token);viewVersion++;ConfigureWatch(path);Interlocked.Exchange(ref dirty,0);
   var job=new ScanProcess(path);scan=job;job.Progress+=(line)=>Ui(()=>{if(generation==token&&scan==job)ShowProgress(line);});Busy.Visible=true;Status.Text="분석 시작 · "+path;UpdateButtons();
   try{var value=await job.Run();if(closing||generation!=token)return;snapshot=value.cancelled&&previous!=null?previous:value;focus=retain?Math.Min(focus,snapshot.nodes.Length-1):0;history.Clear();Status.Text=(value.cancelled?"중지됨 · ":"분석 완료 · ")+value.files.ToString("N0")+"개 파일 · "+value.folders.ToString("N0")+"개 폴더 · "+value.elapsedSeconds.ToString("N2")+"초 · 오류 "+value.errors+" · 경계 제외 "+value.excluded;if(value.cancelled&&previous!=null)Status.Text+=" · 이전 완료 결과 유지";
    RefreshProjection();
   }catch(Exception ex){if(!closing)Status.Text="분석 실패: "+ex.Message;}
   finally{if(scan==job){scan=null;Busy.Visible=false;}job.Dispose();if(!closing)UpdateButtons();}
  }
  internal void CancelScan(){if(scan!=null){scan.Cancel();CancelButtonUI.Enabled=false;Status.Text="중지 요청 · 파일 작업 종료를 기다리는 중";}}
  void UpdateCapacity(string path,long token){Task.Run(()=>{try{var drive=new DriveInfo(Path.GetPathRoot(path));return "볼륨 여유 "+Display.Bytes((ulong)drive.AvailableFreeSpace)+" / "+Display.Bytes((ulong)drive.TotalSize);}catch{return "볼륨 여유 조회 불가";}}).ContinueWith(t=>Ui(()=>{if(token==generation&&!closing)CapacityLabel.Text=t.Result;}));}
  void ShowProgress(string line){try{var obj=Snapshot.Serializer().Deserialize<Dictionary<string,object>>(line);object kind;if(!obj.TryGetValue("type",out kind)||Convert.ToString(kind)!="progress")return;Status.Text="분석 중 · 파일 "+Convert.ToInt32(obj["files"]).ToString("N0")+" · 폴더 "+Convert.ToInt32(obj["folders"]).ToString("N0")+" · 대기 "+obj["pending"]+" · 오류 "+obj["errors"];PathLabel.Text=Convert.ToString(obj["current"]);Total.Text=Display.Bytes(Convert.ToUInt64(obj[Logical.Checked?"logical":"allocated"]));
    if(obj.ContainsKey("roots")){var nodes=Snapshot.Serializer().Deserialize<Node[]>(Snapshot.Serializer().Serialize(obj["roots"]));var rows=new List<Node>();rows.Add(new Node{id=0,name="관측 개요",directory=true,children=Enumerable.Range(1,nodes.Length).ToArray()});foreach(var n in nodes){n.id=rows.Count;n.parent=0;n.children=new int[0];rows.Add(n);}var partial=new Snapshot{nodes=rows.ToArray()};var weights=new ulong[rows.Count];foreach(var n in nodes)weights[n.id]=Logical.Checked?n.logical:n.allocated;Map.ShowProjection(new Projection{Source=partial,Weights=weights,Children=rows[0].children,Focus=0});PathLabel.Text="빠른 개요 · 현재까지 관측 · "+Convert.ToString(obj["current"]);}}catch{} }
  internal void Navigate(int id,bool remember){if(snapshot==null||id<0||id>=snapshot.nodes.Length)return;if(!snapshot.nodes[id].directory){SelectNode(id);return;}if(id!=focus&&remember)history.Push(focus);focus=id;RefreshProjection();}
  internal void RefreshProjection(){if(snapshot==null)return;var source=snapshot;int current=focus,token=++viewVersion;string expression=FilterBox.Text;bool logical=Logical.Checked,hidden=Hidden.Checked;projecting=true;FilterError.Text="";
   Task.Run(()=>Projection.Build(source,current,expression,logical,hidden)).ContinueWith(task=>Ui(()=>{if(closing||token!=viewVersion||snapshot!=source)return;projecting=false;if(task.IsFaulted){FilterError.Text=task.Exception.GetBaseException().Message;return;}projection=task.Result;Listing.VirtualListSize=0;Listing.VirtualListSize=projection.Children.Length;Map.ShowProjection(projection);Total.Text=Display.Bytes(projection.Weights[focus]);PathLabel.Text=(offline?"오프라인 · ":"")+source.nodes[focus].path;UpdateButtons();}));
  }
  void RetrieveItem(object sender,RetrieveVirtualItemEventArgs e){if(projection==null||e.ItemIndex<0||e.ItemIndex>=projection.Children.Length){e.Item=new ListViewItem("");return;}Node n=projection.Source.nodes[projection.Children[e.ItemIndex]];var item=new ListViewItem((n.directory?"▸ ":"")+n.name);item.SubItems.Add(Display.Bytes(n.allocated));item.SubItems.Add(Display.Bytes(n.logical));item.SubItems.Add(n.error.HasValue?"오류 "+n.error:n.boundary?"재분석 경계 · 따라가지 않음":n.directory?"폴더":"파일");e.Item=item;}
  int SelectedId(){return projection!=null&&Listing.SelectedIndices.Count>0&&Listing.SelectedIndices[0]<projection.Children.Length?projection.Children[Listing.SelectedIndices[0]]:-1;}
  void SelectNode(int id){if(snapshot==null||id<0||id>=snapshot.nodes.Length)return;Node n=snapshot.nodes[id];Map.SelectNode(id);Status.Text=n.path+" · 디스크 "+Display.Bytes(n.allocated)+" · 논리 "+Display.Bytes(n.logical)+(n.error.HasValue?" · "+new Win32Exception((int)n.error.Value).Message:"")+(n.boundary?" · junction/symlink 경계 제외":"");}
  void UpdateButtons(){ScanButton.Enabled=scan==null;RescanButton.Enabled=scan==null&&snapshot!=null&&!offline;CancelButtonUI.Enabled=scan!=null;UpButton.Enabled=snapshot!=null&&snapshot.nodes[focus].parent.HasValue;BackButton.Enabled=history.Count>0;RootButton.Enabled=snapshot!=null&&focus!=0;}
  void SaveSnapshot(){if(snapshot==null)return;using(var d=new SaveFileDialog{Filter="JSON 스냅샷|*.json",FileName="SpaceSniffer.json"})if(d.ShowDialog(this)==DialogResult.OK)try{SaveTo(d.FileName);Status.Text="스냅샷 저장: "+d.FileName;}catch(Exception ex){MessageBox.Show(this,ex.Message,"저장 오류");}}
  internal void SaveTo(string path){var source=snapshot;AtomicFile.Write(path,writer=>writer.Write(Snapshot.Serializer().Serialize(source)));}
  void LoadSnapshot(){if(scan!=null)return;using(var d=new OpenFileDialog{Filter="JSON 스냅샷|*.json"})if(d.ShowDialog(this)==DialogResult.OK)OpenSnapshot(d.FileName);}
  internal async void OpenSnapshot(string path){if(scan!=null)return;long token=++generation;try{var value=await Task.Run(()=>Snapshot.Load(path));if(closing||token!=generation)return;snapshot=value;offline=true;CapacityLabel.Text="오프라인 스냅샷";ConfigureWatch();focus=0;history.Clear();Map.Clear();RefreshProjection();Status.Text="오프라인 스냅샷: "+path;}catch(Exception ex){Status.Text="스냅샷 오류: "+ex.Message;}}
  void Export(){if(projection==null)return;using(var d=new SaveFileDialog{Filter="UTF-8 파일 목록|*.txt",FileName="SpaceSniffer-files.txt"})if(d.ShowDialog(this)==DialogResult.OK)try{ExportTo(d.FileName);Status.Text="파일 목록 저장: "+d.FileName;}catch(Exception ex){MessageBox.Show(this,ex.Message,"내보내기 오류");}}
  internal void ExportTo(string path){if(projection==null)throw new InvalidOperationException("표시 계산 중입니다.");var source=projection;var stack=new Stack<int>();stack.Push(focus);AtomicFile.Write(path,writer=>{writer.WriteLine("path\tlogical_bytes\tallocated_bytes\ttype");while(stack.Count>0){Node n=source.Source.nodes[stack.Pop()];if(source.Weights[n.id]==0)continue;writer.WriteLine(n.path.Replace("\t"," ")+"\t"+n.logical+"\t"+n.allocated+"\t"+(n.directory?"directory":"file"));for(int i=n.children.Length-1;i>=0;i--)stack.Push(n.children[i]);}});}
  void ShowIssues(){if(snapshot==null)return;var form=new Form{Text="접근 오류 · 제외한 경계",Size=new Size(950,500),StartPosition=FormStartPosition.CenterParent};var list=new ListView{Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true};list.Columns.Add("경로",600);list.Columns.Add("원인",310);foreach(var n in snapshot.nodes.Where(n=>n.error.HasValue||n.boundary)){string reason=n.boundary?"reparse point · 대상 자동 탐색 제외":new Win32Exception((int)n.error.Value).Message+" ("+n.error+")";list.Items.Add(new ListViewItem(new[]{n.path,reason}));}form.Controls.Add(list);form.ShowDialog(this);form.Dispose();}
  void ConfigureWatch(string path=null){if(watcher!=null){watcher.EnableRaisingEvents=false;watcher.Dispose();watcher=null;}if(closing||!Watch.Checked||offline)return;if(path==null&&snapshot!=null)path=snapshot.root;if(path==null||!Directory.Exists(path))return;
   try{watcher=new FileSystemWatcher(path){IncludeSubdirectories=true,InternalBufferSize=65536,NotifyFilter=NotifyFilters.FileName|NotifyFilters.DirectoryName|NotifyFilters.Size|NotifyFilters.LastWrite};watcher.Changed+=Changed;watcher.Created+=Changed;watcher.Deleted+=Changed;watcher.Renamed+=(s,e)=>Changed(s,e);watcher.Error+=(s,e)=>{Interlocked.Exchange(ref dirty,1);};watcher.EnableRaisingEvents=true;}catch(Exception ex){Status.Text="변경 감시 시작 실패: "+ex.Message;}
  }
  void Changed(object sender,FileSystemEventArgs e){string cache=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SpaceSniffer");if(e.FullPath.StartsWith(cache+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))return;Interlocked.Exchange(ref dirty,1);}
  void Ui(Action action){if(closing||IsDisposed)return;try{if(InvokeRequired)BeginInvoke(action);else action();}catch(InvalidOperationException){} }
  void CloseOwnedWork(){closing=true;generation++;viewVersion++;watchTimer.Stop();watchTimer.Dispose();if(watcher!=null){watcher.Dispose();watcher=null;}if(scan!=null){scan.Dispose();scan=null;} }
 }
